import json
import re

try:
    from flask import Flask, jsonify
except ImportError:
    # Minimal stand-in so the routes still work where Flask is not installed.
    class _Response:
        def __init__(self, body):
            self.data = body if isinstance(body, str) else json.dumps(body)
            self._json = body if not isinstance(body, str) else None

        def get_json(self):
            return self._json

    def jsonify(obj):
        return _Response(obj)

    class Flask:
        def __init__(self, name):
            self.routes = []

        def route(self, rule):
            int_args = re.findall(r'<int:(\w+)>', rule)

            def convert(m):
                if m.group(1):
                    return '(?P<%s>\\d+)' % m.group(2)
                return '(?P<%s>[^/]+)' % m.group(2)

            pattern = re.sub(r'<(int:)?(\w+)>', convert, rule)
            regex = re.compile('^' + pattern + '$')

            def decorator(func):
                self.routes.append((regex, int_args, func))
                return func
            return decorator

        def test_client(self):
            app = self

            class Client:
                def get(self, path):
                    for regex, int_args, func in app.routes:
                        m = regex.match(path)
                        if m:
                            kwargs = m.groupdict()
                            for k in int_args:
                                kwargs[k] = int(kwargs[k])
                            result = func(**kwargs)
                            return result if isinstance(result, _Response) else _Response(result)
                    return _Response('Not Found')
            return Client()

app = Flask(__name__)


@app.route('/')
def home():
    return 'Welcome to PyMasters!'


@app.route('/hello/<name>')
def hello(name):
    return f'Hello, {name}! Welcome to Flask.'


@app.route('/square/<int:num>')
def square(num):
    return jsonify({'number': num, 'square': num ** 2})


if __name__ == '__main__':
    client = app.test_client()
    response = client.get('/square/5')
    data = response.get_json()
    print(f"Visit /square/5 → {json.dumps({'number': data['number'], 'square': data['square']})}")
